8. assertReplayDeterministic true: build logRef: start from s0 = state(1); s1 = applyAction(s0, { type: 'buy', seat: 0, pileId: 'hg' }); s2 = applyAction(s1, { type: 'endTurn', seat: 0 }); s3 = applyAction(s2, { type: 'buy', seat: 1, pileId: 'kn' }); expect(assertReplayDeterministic(s3)).toBe(true).
